code.C:
#include <stdio.h>

int main() {
    int m;
    if (scanf("%d", &m) == 1) {
        const char* months[] = {"", "January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"};
        if (m >= 1 && m <= 12) printf("%s\n", months[m]);
        else printf("Invalid\n");
    }
    return 0;
}

